 // Computes C = A * B on the calling thread. C is NOT zeroed by the caller.
 // n is any size from 1 to 2048.
 void matmul(int n, const float* A, const float* B, float* C) {
-    for (int i = 0; i < n; ++i)
-        for (int j = 0; j < n; ++j) {
-            float s = 0.0f;
-            for (int k = 0; k < n; ++k) s += A[i * n + k] * B[k * n + j];
-            C[i * n + j] = s;
+    constexpr int IM = 8;   // microkernel rows
+    constexpr int JM = 8;   // microkernel cols
+    constexpr int BK = 64;  // block size for k dimension
+
+    // Zero output matrix once
+    for (size_t i = 0; i < (size_t)n * n; ++i) C[i] = 0.0f;
+
+    for (int i0 = 0; i0 < n; i0 += IM) {
+        for (int j0 = 0; j0 < n; j0 += JM) {
+            // accumulator block IM x JM
+            float acc[IM][JM];
+            for (int ii = 0; ii < IM; ++ii)
+                for (int jj = 0; jj < JM; ++jj)
+                    acc[ii][jj] = 0.0f;
+            for (int k0 = 0; k0 < n; k0 += BK) {
+                int k1 = (k0 + BK < n) ? k0 + BK : n;
+                for (int k = k0; k < k1; ++k) {
+                    // load A panel (IM rows) at column k
+                    float Avec[IM];
+                    for (int ii = 0; ii < IM; ++ii) {
+                        int i = i0 + ii;
+                        Avec[ii] = (i < n) ? A[i * n + k] : 0.0f;
+                    }
+                    // load B panel (JM cols) at row k
+                    float Bvec[JM];
+                    for (int jj = 0; jj < JM; ++jj) {
+                        int j = j0 + jj;
+                        Bvec[jj] = (j < n) ? B[k * n + j] : 0.0f;
+                    }
+                    // outer product update accumulator
+                    for (int ii = 0; ii < IM; ++ii) {
+                        float a = Avec[ii];
+                        for (int jj = 0; jj < JM; ++jj) {
+                            acc[ii][jj] += a * Bvec[jj];
+                        }
+                    }
+                }
+            }
+            // store accumulator block to C
+            for (int ii = 0; ii < IM; ++ii) {
+                int i = i0 + ii;
+                if (i >= n) continue;
+                for (int jj = 0; jj < JM; ++jj) {
+                    int j = j0 + jj;
+                    if (j >= n) continue;
+                    C[i * n + j] += acc[ii][jj];
+                }
+            }
         }
+    }
 }
